[
    DataContract,
    SysOperationGroup('Period', "@RebatesAndDeductions:Period", '1'),
    SysOperationGroup('Scope', "Scope", '2')
]
public final class METRebateCombinedContract
{
    private TAMRebateFromDate fromDate;
    private TAMRebateToDate toDate;
    private TransDate transDate;
    private boolean runInParallel = true;
    private boolean processRebate = true;
    private boolean processWriteOff = true;
    private str packedQuery;
    private boolean initiatePrintInvoice = true;

}

Method.Source:
public static METRebateCombinedContract construct()
{
    return new METRebateCombinedContract();
}

[DataMember, SysOperationDisplayOrder('1'), SysOperationGroupMember('Period')]
public TAMRebateFromDate parmFromDate(TAMRebateFromDate _fromDate = fromDate)
{
    fromDate = _fromDate;

    return fromDate;
}

[DataMember, SysOperationDisplayOrder('2'), SysOperationGroupMember('Period')]
public TAMRebateToDate parmToDate(TAMRebateToDate _toDate = toDate)
{
    toDate = _toDate;

    return toDate;
}

[DataMember, SysOperationDisplayOrder('3'), SysOperationLabel(literalStr("@SYS14475")), SysOperationGroupMember('Period')]
public TransDate parmTransDate(TransDate _transDate = transDate)
{
    transDate = _transDate;

    return transDate;
}

[DataMember, SysOperationDisplayOrder('1'), SysOperationLabel("@GlobalUnifiedPricing:GUPPriceDetail_TabPageRebates"), SysOperationGroupMember('Scope')]
public boolean parmProcessRebate(boolean _processRebate = processRebate)
{
    processRebate = _processRebate;

    return processRebate;
}

[DataMember, SysOperationDisplayOrder('2'), SysOperationLabel("@SYS99195"), SysOperationGroupMember('Scope')]
public boolean parmProcessWriteOff(boolean _processWriteOff = processWriteOff)
{
    processWriteOff = _processWriteOff;

    return processWriteOff;
}

[DataMember, SysOperationDisplayOrder('3'), SysOperationLabel("@MET:METRebateCombinedBatchThread"), SysOperationGroupMember('Scope')]
public boolean parmRunInParallel(boolean _runInParallel = runInParallel)
{
    // Yes = parallel create-trans (one task per work unit, single-threaded posting).
    // No  = single-threaded sequential run over the whole selection.
    runInParallel = _runInParallel;

    return runInParallel;
}

[DataMember, AifQueryType('_packedQuery', queryStr(METRebateCombinedDeals))]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

/// <summary>
/// Initiate Print Invoice to be displayed on UI.
/// </summary>
/// <param name = "metInitiatePrintInvoice">boolean</param>
/// <returns>True if visible; otherwise, false.</returns>
[DataMember, SysOperationLabel(literalStr("Initiate print invoice"))]
public boolean parmInitiatePrintInvoice(boolean _initiatePrintInvoice = initiatePrintInvoice)
{
    initiatePrintInvoice = _initiatePrintInvoice;

    return initiatePrintInvoice;
}
